                <button 
                    onClick={onClose} 
                    className="p-1 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
