import { motion, AnimatePresence } from 'framer-motion';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/80 backdrop-blur-sm"
          />
          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 20 }}
            transition={{ type: "spring", duration: 0.5 }}
            className="relative w-full max-w-md bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl shadow-cyan-900/20 overflow-hidden flex flex-col max-h-[85vh]"
          >
            <div className="flex justify-between items-center p-4 border-b border-slate-800 bg-slate-900 flex-shrink-0">
              <h3 className="text-lg font-bold text-white tracking-tight">{title}</h3>
              <button 
                  onClick={onClose} 
                  className="p-1 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="p-4 overflow-y-auto overscroll-contain">
              {children}
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';

interface CalendarProps {
  selectedDates: string[];
  onDateToggle: (date: string) => void;
}

export const Calendar: React.FC<CalendarProps> = ({ selectedDates, onDateToggle }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year: number, month: number) => {
    return new Date(year, month, 1).getDay();
  };

  const formatDate = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  const days = [];
  // Empty slots for prev month
  for (let i = 0; i < firstDay; i++) {
    days.push(null);
  }
  // Days
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(new Date(year, month, i));
  }

  const handlePrevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  const isSelected = (date: Date) => {
    return selectedDates.includes(formatDate(date));
  };

  const isWeekend = (date: Date) => {
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() && 
           date.getMonth() === today.getMonth() && 
           date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="w-full select-none max-w-sm mx-auto">
      <div className="flex justify-between items-center mb-4">
        <button 
            onClick={handlePrevMonth} 
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
        </button>
        <h3 className="text-white font-bold text-base font-mono">
            {currentDate.toLocaleDateString('default', { month: 'long', year: 'numeric' })}
        </h3>
        <button 
            onClick={handleNextMonth} 
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
            </svg>
        </button>
      </div>

      <div className="grid grid-cols-7 gap-1 mb-2">
        {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
            <div key={day} className="text-center text-[10px] text-slate-500 uppercase font-bold py-1">
                {day}
            </div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {days.map((date, index) => {
            if (!date) return <div key={`empty-${index}`} />;

            const selected = isSelected(date);
            const weekend = isWeekend(date);
            const today = isToday(date);
            const dateStr = formatDate(date);

            return (
                <motion.button
                    key={dateStr}
                    whileTap={{ scale: 0.9 }}
                    onClick={() => onDateToggle(dateStr)}
                    className={`
                        aspect-square rounded-md flex flex-col items-center justify-center text-xs relative transition-colors duration-200 touch-manipulation
                        ${selected ? 'bg-cyan-600 text-white shadow-[0_0_10px_rgba(8,145,178,0.4)]' : 
                          weekend ? 'bg-slate-900/30 text-slate-700' : 'bg-slate-800/40 text-slate-300 hover:bg-slate-700'}
                        ${today ? 'ring-1 ring-cyan-500/50' : ''}
                    `}
                >
                    <span className="relative z-10">{date.getDate()}</span>
                    {selected && (
                        <motion.div 
                            layoutId="selected-indicator"
                            className="absolute inset-0 border border-cyan-400/50 rounded-md" 
                            initial={false}
                        />
                    )}
                    {today && !selected && (
                         <div className="absolute bottom-1 w-1 h-1 bg-cyan-400 rounded-full" />
                    )}
                </motion.button>
            );
        })}
      </div>

      <div className="mt-4 flex flex-col sm:flex-row gap-2 text-[10px] text-slate-500 justify-center">
        <div className="flex items-center gap-2 bg-slate-800/50 p-2 rounded-lg justify-center">
            <div className="w-2.5 h-2.5 bg-cyan-600 rounded shadow-[0_0_5px_rgba(8,145,178,0.5)] flex-shrink-0"></div>
            <span>Selected Holiday</span>
        </div>
        <div className="flex items-center gap-2 bg-slate-800/50 p-2 rounded-lg justify-center">
            <div className="w-2.5 h-2.5 bg-slate-900/30 border border-slate-700 rounded flex-shrink-0"></div>
            <span>Weekend</span>
        </div>
      </div>
    </div>
  );
};
